const session = global.get("parat_bridge.ropc_session");
if (!session || !session.enrichedToken) {
    node.warn("[BOOST] No ROPC session available for incident resolution");
    return null;
}

msg.url = session.apiUrl + "/restapi/periodic/"
    + session.projectId + "/incidents/" + session.userId;
msg.headers = {
    "Authorization": "Bearer " + session.enrichedToken
};

return msg;

const incidents = msg.payload;
if (!Array.isArray(incidents)) {
    node.warn("[BOOST] Unexpected incidents response");
    return null;
}

const connections = global.get("parat_bridge.connections") || {};
let resolved = 0;

for (const [name, conn] of Object.entries(connections)) {
    for (const [id, client] of Object.entries(conn.clients || {})) {
        if (client.client_system !== "rayvn") continue;

        const logName = client.client_specific?.log_name || client.name;
        const match = incidents.find(inc => inc.name === logName);

        if (match) {
            client.client_specific.incident_id = match.id;
            resolved++;
        } else {
            node.warn("[BOOST] No incident match for log: " + logName);
        }
    }
}

global.set("parat_bridge.connections", connections);
node.status({
    fill: resolved > 0 ? "green" : "yellow",
    shape: "dot",
    text: resolved + " resolved " + new Date().toLocaleTimeString()
});

return msg;
